DROP TABLE invitation_schema;CREATE TABLE invitation_schema (singleton INTEGER PRIMARY KEY CHECK(singleton=1), version INTEGER NOT NULL CHECK(version=4)) STRICT;CREATE TRIGGER invitation_cleanup_guard BEFORE DELETE ON invitation_consents WHEN NOT (CASE WHEN OLD.broker_ticket IS NULL THEN OLD.broker_enrollment IS NULL WHEN json_valid(OLD.broker_ticket) THEN coalesce((json_type(OLD.broker_ticket)='object' AND (SELECT count(*) FROM json_each(OLD.broker_ticket))=2 AND json_type(OLD.broker_ticket,'$.ticket_id')='text' AND json_type(OLD.broker_ticket,'$.scope_hash')='text' AND length(CAST(OLD.broker_ticket AS BLOB))<=256 AND length(json_extract(OLD.broker_ticket,'$.ticket_id'))=36 AND substr(json_extract(OLD.broker_ticket,'$.ticket_id'),9,1)='-' AND substr(json_extract(OLD.broker_ticket,'$.ticket_id'),14,1)='-' AND substr(json_extract(OLD.broker_ticket,'$.ticket_id'),19,1)='-' AND substr(json_extract(OLD.broker_ticket,'$.ticket_id'),24,1)='-' AND length(replace(json_extract(OLD.broker_ticket,'$.ticket_id'),'-',''))=32 AND replace(json_extract(OLD.broker_ticket,'$.ticket_id'),'-','') NOT GLOB '*[^0-9a-f]*' AND length(json_extract(OLD.broker_ticket,'$.scope_hash'))=64 AND json_extract(OLD.broker_ticket,'$.scope_hash') NOT GLOB '*[^0-9a-f]*' AND (OLD.broker_enrollment IS NULL OR OLD.broker_enrollment=json_extract(OLD.broker_ticket,'$.ticket_id'))),0) ELSE 0 END) BEGIN SELECT RAISE(ABORT,'migration_remediation: broker cleanup reference missing or incompatible'); END;INSERT INTO invitation_schema VALUES(1,4);